function check(input, actual, expected) {
  const s = input[0];
  if (typeof actual !== 'string' || actual.length !== s.length) return false;
  const want = {};
  for (const c of s) want[c] = (want[c] || 0) + 1;
  const seen = new Set();
  let previous = Infinity;
  let i = 0;
  while (i < actual.length) {
    const c = actual[i];
    let j = i;
    while (j < actual.length && actual[j] === c) j++;
    const run = j - i;
    if (seen.has(c) || want[c] !== run || run > previous) return false;
    seen.add(c);
    previous = run;
    i = j;
  }
  return true;
}

