function validate([s]) {
  if (s.length < 1 || s.length > 500000) return 's needs 1 to 5 * 10^5 characters.';
  if (!/^[A-Za-z0-9]+$/.test(s)) return 's may contain only English letters and digits.';
  return null;
}

