function frequencySort(s) {
  const count = new Map();
  for (const ch of s) {
    count.set(ch, (count.get(ch) || 0) + 1);
  }

  const buckets = Array.from({ length: s.length + 1 }, () => []);
  for (const [ch, freq] of count) {
    buckets[freq].push(ch);
  }

  const parts = [];
  for (let freq = s.length; freq >= 1; freq--) {
    for (const ch of buckets[freq]) {
      parts.push(ch.repeat(freq));
    }
  }
  return parts.join('');
}

