function frequencySort(s) {
  const chars = s.split('');
  const tally = {};
  for (const c of chars) tally[c] = (tally[c] || 0) + 1;
  chars.sort((a, b) => tally[b] - tally[a] || (a < b ? -1 : a > b ? 1 : 0));
  return chars.join('');
}

