function generate(rand, size) {
  const all = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
  const alphabet = size === 'large' ? all : ['ab', 'aAbB', 'xyz19', 'aA0', all][Math.floor(rand() * 5)];
  const n = size === 'large' ? 10000 : 1 + Math.floor(rand() * 14);
  // Skewed weights make some characters much more frequent than others.
  const weights = Array.from(alphabet, () => Math.pow(rand(), 3) + 0.01);
  const total = weights.reduce((a, b) => a + b, 0);
  let s = '';
  for (let i = 0; i < n; i++) {
    let pick = rand() * total, k = 0;
    while (k < alphabet.length - 1 && pick >= weights[k]) { pick -= weights[k]; k++; }
    s += alphabet[k];
  }
  return [s];
}
